import requests, re
from bs4 import BeautifulSoup
for pmcid in ['PMC4262054','PMC5570371']:
 r=requests.get(f'https://www.ebi.ac.uk/europepmc/webservices/rest/{pmcid}/fullTextXML')
 print('\n###',pmcid,r.status_code)
 soup=BeautifulSoup(r.text,'xml')
 txt=' '.join(soup.get_text(' ').split())
 pats=['hypertension was defined','defined as','blood pressure','logistic regression','odds ratio','P<','P =','CMV IgG','4.25','4.85','Table 2','Table 3','Table 4']
 for p in pats:
  hits=[m.start() for m in re.finditer(re.escape(p),txt,re.I)]
  if hits:
   print('\n',p)
   for i in hits[:3]: print(txt[max(0,i-250):i+500])
